update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p116","body":"یوں ملنے کو مجھے کیا ملا نہیں\nجو چاہا تھا بس وہی ملا نہیں\n\nجس کی تلاش میں رہتا ہے زمانہ\nمیں نے کبھی وہ سکوں ڈھونڈا نہیں\n\nکچھ کہنے، خود چل کر آئی تھی زندگی\nکیا کہہ کر گئی ہے، میں نے سنا نہیں\n\nاک ترے ہونے سے یہ شہر تھا آباد\nتو نہیں تو یہ شہر بھی اپنا نہیں\n\nسنو کہ اک فقط تمہارے سوا\nدیکھے بہت پر کوئی دکھا نہیں\n\nنہ رونے کا سلیقہ آیا ، نہ ہنسنے کی تمنا\nمجھے کبھی کچھ ڈھنگ سے آیا نہیں\n\nغفلت میں گزری ہے زندگی ساری\nکیا سے کیا ہوگیا میں جانتا نہیں\n\nکسے ڈھونڈتے پہنچے ہو اس دہلیز تک\nاس دل میں اب کوئی  بھی رہتا نہیں\n\nذاھد مجھ سے رکھ سچ کی توقع\nاحمد ؔ گمراہ سہی کوئی مُلّا نہیں"},{"slug":"tum-p117","body":"دل میں جانے کیسی یہ جستجو آئے\nتجھ سے کلام بھی نہ کروں اور تو روبرو آئے\n\nتجھ سے ہو باتیں دین و دل کی ہزار\nمیری پلکوں پہ شان سے تیری آبرو آئے\n\nتو جو میری بانہوں سے کبھی ہو دور\nہونٹ ہنسنا بھولیں، آنکھوں سے لہو آئے\n\nتو جو رخ موڑ لے تو جی کجے میرا\nپھر اک دم سے تیری زلفوں کی خوشبو آئے\n\nمجھ سے کر اس طرح سے ترک وفا جاناں\nمیرا ہجر میں جی لگے اور وصل کی آرزو آئے\n\nتھام لے میرے خوابوں کو اور پھر مٹا دے\nمیرے سپنوں میں کسی صورت تو قابو آئے\n\nہم ہر شعر تیری ذات کے حوالے کر کے\nاحمد ؔ واپس تیری بزم سے بےآبرو آئے"},{"slug":"tum-p118","body":"احمد ؔ  لکھتا ہوں زندگی کے افسانے کو\nخوبصورت لوگ ملتے ہیں بچھڑ جانے کو"},{"slug":"tum-p119","body":"تو جو اگر ملا ہوتا\nزندگی سے کیا گلہ ہوتا\n\nتم سے بجھڑ گیا تھا ورنہ\nمیں خود میں ایک قافلہ ہوتا\n\nاگر ایک سے زیادہ عشق ہوتا\nپھر ایک سے زیادہ قبلہ ہوتا\n\nہم اپنی جانب سے ہی مبتلا رہے\nکچھ درمیاں ہوتا تو مشورہ ہوتا\n\nدل سے بھی بڑھ کر ہونا تھا\nدل توڑنے کا اگر کفارہ ہوتا\n\nحقیقت کو میں فسانہ لکھتا\nاحمد ؔ حسن اگر باوفا ہوتا\n\nباتیں تو بہت اچھی بنا لیتا ہے\nاحمد ؔ شاعر نہ ہوتا تو جھوٹا ہوتا"},{"slug":"tum-p120","body":"اب کہ اس درجہ شوق منزل نہیں\nدور دور تک کوئی ساحل نہیں\nکوئی ربط نہیں ، راہ نہیں\nکوئی سبب نہیں ، چاہ نہیں\nذوق بد زوق ہے جنوں نہیں\nآرزو شکستہ ہے سکوں نہیں\nکسی قسم کے مراسم نہیں\nاشک نہیں تبسم نہیں\nغم ہستی کی کوئی بزم نہیں\nوصل ہجراں کی رسم نہیں\nخوف نہیں غم نہیں\nاب کہ تم اور ہم نہیں"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
